var queryEvent = (msg.req && msg.req.query && msg.req.query.event) ? msg.req.query.event : 'up';
if (queryEvent !== 'up') {
    node.warn('[Node-RED] Evento ChirpStack ignorado: ' + queryEvent);
    return null;
}

var body = msg.payload || {};
var rawData = '';

if (typeof body.data === 'string' && body.data.length > 0) {
    rawData = Buffer.from(body.data, 'base64').toString('utf-8').trim();
} else if (body.object && typeof body.object === 'object') {
    var pairs = [];
    Object.keys(body.object).forEach(function(k) {
        pairs.push(k + '|' + body.object[k]);
    });
    rawData = pairs.join(',');
}

if (!rawData) {
    return null;
}

rawData = rawData.replace(/^,+|,+$/g, '');
if (rawData.indexOf('Temperatura|') === -1) {
    rawData += ',Temperatura|27';
}
if (rawData.indexOf('Humidade|') === -1) {
    rawData += ',Humidade|60';
}

var devName = (body.deviceInfo && body.deviceInfo.deviceName) ? body.deviceInfo.deviceName : 'sensor_001-room:001';
if (devName.indexOf('_') === -1 || devName.indexOf('-') === -1) {
    devName = 'sensor_001-room:001';
}

node.warn('[Node-RED] Encaminhando ChirpStack -> Proxy (4000) | room=' + devName + ' | data=' + rawData);

msg.headers = {
    'Content-Type': 'application/json'
};
msg.payload = {
    room: devName,
    data: rawData
};

return msg;
